'use strict';
function lessonLinks(ids){return ids.map(id=>{const l=lessons.find(x=>x.id===id);return l?`<li><a href="#lesson/${l.id}">${esc(l.title)}</a></li>`:''}).join('');}
function pathways(){const paths=[
{year:'EY',title:'Discover and build habits',focus:'Explore your interests, practise study and digital skills, and connect learning with future possibilities.',ids:['foundation-identity','foundation-goals','foundation-digital','explore-pathways'],outputs:['A strengths and interests profile with real examples','A weekly study plan and typing baseline','A comparison of possible education routes','A small community contribution or legacy plan'],meeting:'Explain two interests, one academic goal and one question to your counsellor. Review what helped you learn.',pace:'Suggested online rhythm: one lesson every two weeks, with practice between sessions.'},
{year:'S4',title:'Explore with evidence',focus:'Investigate programmes, practise short writing, and plan an experience that helps you learn about work.',ids:['3','21','explore-research','explore-interview','foundation-communication','explore-experience','11','8'],outputs:['Programme research notes with sources and dates','A short original writing sample and feedback','An information-session or career-conversation reflection','A supervised holiday project or internship plan'],meeting:'Review your academic goals and questions about courses, testing and summer plans. Use practice tests only when relevant to your pathway.',pace:'Suggested online rhythm: one or two lessons a month, alongside school workshops.'},
{year:'S5',title:'Build your application portfolio',focus:'Develop an informed shortlist, draft your writing and organise testing and application requirements.',ids:['4','39','9','29','30','career-portfolio','41','42','8','explore-experience'],outputs:['Detailed research profiles; the curriculum benchmark is eight institutions across at least three countries','A realistic shortlist; the curriculum suggests five to seven institutions, adjusted with your counsellor','A strong personal essay or motivation-letter draft','A test-preparation and application plan based on actual requirements'],meeting:'Discuss your portfolio, progress and affordable options. Identify your S6 priorities and a productive vacation plan.',pace:'Suggested online rhythm: one lesson a week during an eight-to-ten-week preparation block, with separate writing time.'},
{year:'S6',title:'Refine, submit and prepare',focus:'Finish your application materials, confirm funding and deadlines, and plan what happens after decisions.',ids:['13','12','38','32','40','14','15','45','43','19','20','career-transition'],outputs:['Accurate activities, honours and awards list','Requested recommendations and supporting information; follow each institution’s required number','Final writing reviewed against each prompt','A checked application tracker, funding comparison and post-graduation plan'],meeting:'Bring your actual deadlines, document status and unresolved funding questions. Arrange individual reviews early enough to act on feedback.',pace:'Suggested online rhythm: targeted lessons and individual reviews around your deadlines; preserve time for schoolwork.'}
];main.innerHTML=`<div class="page-top"><p class="eyebrow">Start where you are</p><h1>Your EY–S6 learning pathway</h1><p class="intro">Choose your year group for a suggested sequence. You can open any lesson and revisit earlier work as your interests develop.</p><p>These paths adapt the supplied ASYV Further Education Pathway curriculum. School workshops, practice tests and counsellor meetings remain part of your learning; the online course supports them.</p></div><nav class="year-jumps" aria-label="Year groups">${paths.map(p=>`<a href="#pathways" data-year="${p.year}">${p.year}</a>`).join('')}</nav><div class="year-grid">${paths.map(p=>`<section class="year-card" id="year-${p.year}"><span class="year-badge">${p.year}</span><h2>${p.title}</h2><p>${p.focus}</p><h3>Suggested lessons</h3><ol>${lessonLinks(p.ids)}</ol><h3>Your portfolio checkpoint</h3><ul>${p.outputs.map(o=>`<li>${o}</li>`).join('')}</ul><div class="checkpoint"><strong>Counsellor conversation</strong><p>${p.meeting}</p></div><p class="small muted">${p.pace}</p><a class="button" href="#lesson/${p.ids[0]}">Begin this pathway</a></section>`).join('')}</div><section class="work-entry"><h2>Check progress with evidence</h2><p>At each review, bring your latest work, explain what you learned and agree one next action. Suggested school targets are not admission guarantees or rules for every institution. Your pathway can include university, TVET or another appropriate training route.</p><p>Source: supplied CRC Further Education Pathway Curriculum Outline, updated 29 August 2025, especially pages 1–10. The sequence above is an online adaptation.</p></section>`;document.querySelectorAll('[data-year]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById('year-'+a.dataset.year).scrollIntoView({behavior:'smooth',block:'start'});});}
function roadmap(){const steps=[
['Explore careers','Identify interests, strengths and work values.','foundation-identity'],
['Gather your evidence','Keep examples of learning, activities and contribution.','22'],
['Research your options','Compare academic, personal and financial fit.','21'],
['Check testing needs','Verify each programme’s policy before planning tests.','8'],
['Plan funding early','Check eligibility, full costs and aid requirements.','14'],
['Refine your list','Use research and affordability to revise your options.','4'],
['Build your CV','Describe your own responsibilities and contributions.','38'],
['Set your strategy','Track deadlines and request recommendations in time.','5'],
['Write and revise','Respond to the prompt using your own experiences.','9'],
['Audit and submit','Check documents, payments and submission confirmation.','45'],
['Compare offers','Calculate the remaining cost and check conditions.','19'],
['Prepare for transition','Confirm your next steps and support contacts.','career-transition']
];main.innerHTML=`<div class="page-top"><p class="eyebrow">See the whole journey</p><h1>Your application roadmap</h1><p class="intro">Use these twelve milestones to find your next lesson. Several tasks overlap: start research, funding and deadline planning early, and revisit them as your options change.</p></div><ol class="roadmap-grid">${steps.map((s,i)=>`<li><span class="step-number">${String(i+1).padStart(2,'0')}</span><h2>${s[0]}</h2><p>${s[1]}</p><a href="#lesson/${s[2]}">Open related lesson</a></li>`).join('')}</ol><section class="work-entry"><h2>Use the supplied posters in context</h2><p>The Pathway Admissions image and Princeton Review poster offer a US-oriented overview. This course adapts their planning ideas for students in Rwanda.</p><ul><li><strong>Financial aid:</strong> most foreign citizens are not eligible for US federal student aid; qualifying noncitizen categories exist. Check eligibility before treating FAFSA as a task. Follow each university’s instructions for international aid.</li><li><strong>Early Decision:</strong> it is a binding commitment, not a shortcut suitable for everyone. Discuss fit, affordability and the agreement with your counsellor before applying.</li><li><strong>Tests and scholarships:</strong> verify current test policies and scholarship eligibility for your own circumstances. A practice-test score is not an admission prediction.</li><li><strong>Statistics and paid services:</strong> the poster’s acceptance rates and average scores are a source snapshot, not current requirements. Its commercial services are optional and are not required to complete this course.</li></ul><p class="small">Official context: <a href="https://studentaid.gov/sites/default/files/international-students.pdf" target="_blank" rel="noopener">Federal Student Aid: international students</a> and <a href="https://www.nacacnet.org/early-to-rise-early-to-college-early-applications-in-the-admission-process/" target="_blank" rel="noopener">NACAC: early applications</a>. Reviewed 30 September 2026.</p></section><section class="work-entry"><h2>College Admissions Roadmap</h2><p>Supplied image credited to Pathway Admissions. The linked milestones above provide a readable text alternative.</p><a href="assets/college-application-roadmap.jpg" target="_blank" rel="noopener"><img class="lesson-graphic" src="assets/college-application-roadmap.jpg" alt="Pathway Admissions roadmap showing career exploration, activities, college research, testing, funding, CV, strategy, essays, submission, aid review and decisions."></a><a class="button secondary" href="assets/college-application-roadmap.jpg" download>Download roadmap image</a></section><section class="work-entry"><h2>The Princeton Review College Roadmap</h2><p>Supplied two-page, 24 × 18-inch PDF. Page 2 shows the high-school journey; page 1 includes US admissions advice and commercial information.</p><a href="assets/college-roadmap-poster.pdf#page=2" target="_blank" rel="noopener"><img class="lesson-graphic" src="assets/roadmap-poster-preview.png" alt="Princeton Review illustrated high-school journey from exploring interests through college decisions. Open the PDF for full-size reading."></a><a class="button secondary" href="assets/college-roadmap-poster.pdf" download>Download printable poster PDF</a></section>`;}
function careerResources(){const groups=[['1','Beginning your journey','Explore identity, communication, decisions and goals.','foundation-identity'],['2','Know yourself','Connect interests, values and strengths to possible pathways.','foundation-identity'],['3','Explore careers','Research training routes and learn from supervised experiences.','explore-pathways'],['4','Strategies for success','Practise applications, teamwork and professional habits.','career-portfolio'],['5','What comes next','Prepare a budget, support map and next-step plan.','career-transition']];main.innerHTML=`<div class="page-top"><p class="eyebrow">Explore the supplied resource pack</p><h1>Career readiness resources</h1><p class="intro">All 38 supplied topics from <em>Empower Your Future: Career Readiness Curriculum Guide</em>, organised into five units. Use the adapted course lessons first; the original PDFs are optional reading and facilitator resources.</p><div class="actions"><a class="button" href="#lesson/foundation-identity">Start the adapted lessons</a><a class="button secondary" href="#pathways">Choose your year-group path</a></div></div><div class="resource-context"><h2>Read the originals with context</h2><p>The pack was written for a US setting and includes older links, Massachusetts services, US payroll forms and local legal examples. These are not Rwanda requirements. No Mass CIS account or paid service is needed for the adapted activities. Check local, current requirements before acting on location-specific advice.</p><p>The supplied Further Education Pathway curriculum informs the year-group paths and lessons. Its internal-use source file is not published here. The two supplied posters are available on the <a href="#roadmap">visual roadmap page</a>.</p></div>${groups.map(g=>`<section class="resource-unit"><div><p class="eyebrow">Unit ${g[0]}</p><h2>${g[1]}</h2><p>${g[2]}</p><a href="#lesson/${g[3]}">Open related course lesson</a></div><ul>${window.CAREER_TOPICS.filter(t=>String(t.group)===g[0]).map(t=>`<li><a href="${esc(t.file)}" target="_blank" rel="noopener">${esc(t.title)}</a><span class="small muted">Original PDF</span></li>`).join('')}</ul></section>`).join('')}<p class="small muted">Original PDFs retain their source credits and wording. Adapted course explanations, fictional examples and workbook tasks are newly written. The 50-page college guide remains a separate companion to the original ten modules.</p>`;}
